// TH14 v1.00b Stage 6 boss non-spell (Boss1), source st06bs.ecl.txt:76-119.
// Closure: Boss1_at 121-159 (firing), EffChargePoint2 176-186 (pure anm, omitted).
// Entry state from task: position (0,128); hurt/hit 48x48 -> r=24;
// moveLimit(0,128,280,64) -> clamp x[-140,140], y[96,160].

const TH14_PELLET2: int = 368;   // source etSprite type 1 -> target TH18 type 1
const TIME_LIMIT: int = 2524;    // 120 opening + 2100 source timer + 300 tail + 4 startup
const OPENING_BUFFER: int = 120;

// Source EX slot 1 etExSet(0,1,0,2097152,30,-999999,<difficulty speed>,-999999)
// = VELTIME a=30 along the current angle. Target: fixed cartesian ramp for 30 ticks.
xformdef VELTIME30(gx: fx, gy: fx) {
    set_gravity(gx, gy);
    wait(30);
    set_gravity(0fx, 0fx);
}

// One etOn burst of Boss1_at (source 129-151); b is the running base angle in BAM.
sub boss_at_burst(color: int, b: int) {
    // etAngle(0, B + RANDF2*0.2617994, 0): signed unit draw, 15deg (0.2617994 rad) amplitude.
    var jit: int = (2731fx * ((rand(65536) - 32768) as fx / 32768)) as int;
    // etOffsetRad(0, RANDRAD, RANDF2*64): full-circle direction, signed 64px radius.
    var off_a: angle = rand(65536) as angle;
    var off_d: fx = 64fx * ((rand(65536) - 32768) as fx / 32768);
    // etSpeed(0, RANDF2*1.0, 0): signed initial scalar speed in [-1,1).
    var s0: fx = (rand(65536) - 32768) as fx / 32768;
    // Value pushed for etExSet r: 2.0+RANDF2*1.6; Lunatic (!LO) 0.6+RAND*3.6.
    var target: fx = 2.0fx;
    if global(GVAR_RANK) == 3 {
        target = 0.6fx + (rand(65536) as fx / 65536) * 3.6fx;
    } else {
        target = 2.0fx + ((rand(65536) - 32768) as fx / 32768) * 1.6fx;
    }
    var a: angle = (b + jit) as angle;
    var ux: fx = cos(a);
    var uy: fx = sin(a);
    // EX slot 0 ANIM a=1 keeps position -= 4*velocity at spawn; birth slowdown/nohit omitted.
    var bx: fx = $self_x + off_d * cos(off_a) - 4fx * s0 * ux;
    var by: fx = $self_y + off_d * sin(off_a) - 4fx * s0 * uy;
    var d: fx = (target - s0) / 30fx;
    _ = fire(TH14_PELLET2, color, bx, by, s0, a, VELTIME30(d * ux, d * uy), none);
}

// Boss1_at body: 100 outer steps; E = diffI(rank,1,2,3,4) -> rank+1 bursts per step,
// then B += C and wait(2). E is constant for the run, so it is read once.
sub boss_at_body(color: int, base: int, step: int) {
    var b: int = base;
    var shots: int = global(GVAR_RANK) + 1;
    for it in 0..100 {
        for k in 0..shots {
            boss_at_burst(color, b);
        }
        b = b + step;
        wait(2);
    }
}

// Source: @Boss1_at(...) sync call (caller blocks 200 frames) vs "async" extra context.
sub boss_at_sync(color: int, base: int, step: int) {
    boss_at_body(color, base, step);
}
async sub boss_at_async(color: int, base: int, step: int) {
    boss_at_body(color, base, step);
}

// moveRand(60,4,1.0) recipe (TH16/TH18 movement topic) with this card's limits:
// speed 1 -> 0 linearly over 60 steps, per-frame clamp, direction picked once.
// self int0 = step count, self fx0/1 = logical unit direction.
sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub move_rand() {
    // Source 405b90 = signed unit random * pi; keep the unwrapped int BAM until the end.
    var r: int = rand(65536) - 32768;
    var a: int = 0;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05 rad = 522 BAM.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    arm_next_step();
}

// Every wait inside this attack advances one source movement tick (arm next step first).
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}

// Source 85-100: loop half A (offsets 0..420 of the 840-frame cycle).
sub half_a() {
    card_wait(60);                         // anmPlay/playSound (pure anm) then wait(60)
    spawn boss_at_async(2, 32768, -546);   // @Boss1_at(2, pi, -0.05235988) async
    card_wait(30);
    boss_at_sync(6, 0, 546);               // @Boss1_at(6, 0, 0.05235988) sync, 200 frames
    card_wait(10);
    card_wait(60);                         // anmSelectedPlay (pure anm) then wait(60)
    move_rand();                           // moveRand(60,4,1.0)
    card_wait(60);
}

// Source 101-115: loop half B, colors/bases swapped (offsets 420..840).
sub half_b() {
    card_wait(60);
    spawn boss_at_async(6, 0, 546);
    card_wait(30);
    boss_at_sync(2, 32768, -546);
    card_wait(10);
    card_wait(60);
    move_rand();
    card_wait(60);
}

async sub source_enemy() {
    set_invuln(65535);
    set_hitbox(24fx);     // Boss 27-28 setHurtbox/setHitbox(48,48)
    set_hurtbox(24fx);
    // Source timerReset slot0 timeout = 2100 frames: five 420-frame halves, then stop.
    // BossCard1 (next attack) is not executed; body stays for the tail frames.
    half_a();
    half_b();
    half_a();
    half_b();
    half_a();
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 14000, 0, 0, 0, source_enemy);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
